package com.backend.nutri_predic.plandia.service; import com.backend.nutri_predic.consumo.classification.ResultadoCriterioPcs; import com.backend.nutri_predic.consumo.entity.EvaluacionConsumo; import com.backend.nutri_predic.consumo.repository.DetalleEvaluacionConsumoRepository; import com.backend.nutri_predic.plandia.entity.*; import com.backend.nutri_predic.plandia.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class IntervencionConsumoDiariaService {private final DetalleEvaluacionConsumoRepository detalles;private final IntervencionConsumoDiariaRepository intervenciones;public IntervencionConsumoDiariaService(DetalleEvaluacionConsumoRepository d,IntervencionConsumoDiariaRepository i){detalles=d;intervenciones=i;}@Transactional public void crearPorExcesos(EvaluacionConsumo e,PlanDiario p){if(e.getEstadoClasificacion()!=com.backend.nutri_predic.consumo.entity.EstadoClasificacionConsumo.ALTO)return;for(var d:detalles.findByEvaluacionIdOrderByIdAsc(e.getId()))if(ResultadoCriterioPcs.CUMPLE.name().equals(d.getResultado())&&!intervenciones.existsByEvaluacionConsumoIdAndCriterioEvaluadoId(e.getId(),d.getCriterioEvaluadoId())){var x=new IntervencionConsumoDiaria();x.setCliente(e.getCliente());x.setEvaluacionConsumo(e);x.setPlanDiario(p);x.setCriterioEvaluadoId(d.getCriterioEvaluadoId());x.setComponente(d.getComponente());x.setFuenteExceso(d.getFuente());x.setReferenciaUtilizada(d.getReferenciaAplicada()==null?null:d.getReferenciaAplicada().toPlainString());x.setMensajeEstructurado("SEGUIMIENTO_PCS_CRITERIO_VALIDADO");intervenciones.save(x);}}}
